export type ErrorEntry = {
	message: string,
	file: string | null,
	line: number | null,
	kind: ErrorKind,
	/**
	 *  诊断（roadmap ④）：把 `.log` 原始报错翻译成「原因 + 怎么改」。
	 *  `None` = 匹配不到已知模式，前端降级为原文 + 行号（宁可不说，也不瞎说）。
	 */
	diagnosis: Diagnosis | null,
};

/**  错误分类（design.md 失败语义 + IO 兜底）。 */
export type ErrorKind = "content_error" | "timeout" | "aborted" | "io";

export type ErrorsUpdatedEvent = ErrorEntry[];

/**  失败原因（与 design.md 失败语义三路对应；Aborted = 手动终止）。 */
export type FailureKind = "timeout" | "content_error" | "aborted";

/**  文件写入载荷（save_all 命令输入）。 */
export type FileContent = {
	path: string,
	content: string,
};

/**
 *  files-changed 事件载荷。
 *  `structural`：是否为结构变化（增/删/重命名）。内容修改（如自动保存）为 false——
 *  文件树因此可跳过重建（modules.md §12「文件树增量刷新」）。
 */
export type FilesChanged = {
	paths: string[],
	structural: boolean,
};

export type FilesChangedEvent = FilesChanged;

/**
 *  `synctex_inverse` 命令输出（roadmap ⑤/㉒）。
 * 
 *  为什么不是一个裸的 `SourcePositionDto`：反向定位**可能没有可跳转的源码**——
 *  命中生成产物（`tmp/main.toc` 等）、系统宏包（`article.cls`），或尚未产生同步数据。
 *  这些情况既不该静默失败（用户点了没反应），也不该把生成文件当源码打开。
 *  故：`source = None` 时用 `note` 说明原因；`note` 也可在成功时补充"已回落到最近源码行"。
 */
export type InverseResultDto = {
	/**  可跳转的源码位置；`None` = 该处没有可打开的源码。 */
	source: SourcePositionDto | null,
	/**  给用户看的一句话（失败原因 / 回落说明）；`None` = 正常直连，无需提示。 */
	note: string | null,
};

/**
 *  公式预览的结果（roadmap ㊸ 切片 3）。`hit=false` = 光标不在公式里 ⇒ 前端**不显示**浮层
 *  （这是最常见的情况，不该当成错误）。
 */
export type MathPreviewDto = {
	/**  光标是否落在数学公式里（扫描器口径见 `core::math`）。 */
	hit: boolean,
	/**  片段是否编译成功（`hit=true` 才有意义）。 */
	ok: boolean,
	/**  本次墙钟（毫秒）—— 首次与"同一公式二次"（走 A 闸门）差别很大。 */
	elapsedMs: number,
	/**  缓存键 = `<项目>/tmp/snippet/<键>/` 的目录名。 */
	key: string,
	/**  片段产物路径（成功时）。 */
	pdfPath: string | null,
	/**  `auto` / `button`：首次片段编译 > 3 s ⇒ 该项目退回"悬停出按钮"。 */
	mode: string,
	/**  失败原因（**不留白**：排不出来时给一句话）。 */
	message: string | null,
	/**  命中的公式正文（含定界符；调试与日志用）。 */
	formula: string | null,
};

/**
 *  设置层的一次性提示（状态栏 / 设置面板展示，用户可 dismiss）。
 * 
 *  存在的理由：有些调整**没有可迁移的等价字段**（例如 v2 删掉了引擎设置），只能如实告知
 *  "原设置已忽略"。做成数据而不是一次性弹窗，是因为它要跨重启存活到用户看见为止——
 *  dismiss 后按 `id` 从列表里移除（[`super::merge::apply_patch`]）。
 */
export type Notice = {
	/**  稳定标识（dismiss 按它移除；同一 id 不会重复出现）。 */
	id: string,
	level: NoticeLevel,
	/**  给用户看的一句话。 */
	message: string,
};

/**  一次性提示的级别（前端据此选样式：info = 中性告知，warning = 需要注意）。 */
export type NoticeLevel = "info" | "warning";

/**
 *  文档大纲节点（get_outline 命令输出；解析逻辑见 [`crate::outline`]，2026-09-03 从
 *  前端 `src/stores/outline.ts` 下沉，语义等价、单测锁定）。
 */
export type OutlineNode = {
	/**  标题（`\section[short]{title}` 取 `{...}` 内内容并 trim）。 */
	title: string,
	/**  结构层级：0=part,1=chapter,2=section,3=subsection,4=subsubsection,5=paragraph,6=subparagraph。 */
	level: number,
	/**  项目内绝对路径（已归一化，与前端存储键一致）。 */
	file: string,
	/**  1-based 行号。 */
	line: number,
	/**  文件基名（界面显示用：`file:line`）。 */
	fileBase: string,
	/**  子节点（按文档顺序）。 */
	children: OutlineNode[],
};

/**
 *  pdf-updated 事件载荷。
 * 
 *  `changed_pages` / `pages`（2026-09，docs/archive/research/incremental-edit-x-dvi.md 的 B/C 两个功能点）：
 *  本次编译相对**上一次**变化的页号（1-based、升序）。前端语义：
 *  - `pages > 0` 且 `changed_pages` **非空** → 只有这些页需要重绘，其余页复用 canvas 位图；
 *  - `pages > 0` 且 `changed_pages` **为空** → 逐页字节完全相同 → **跳过重载**（新旧 PDF 逐页等价，
 *    刷新只会白重绘并可能引起视觉跳动）；
 *  - `pages == 0` → **无法判定**（XDV 缺失/损坏/首次运行拿不到）→ 按全量刷新处理。
 */
export type PdfUpdated = {
	path: string,
	/**  本次变化的页号（1-based）；空表 ≠ "无法判定"——后者看 `pages == 0`。 */
	changed_pages: number[],
	/**  本次编译的页数；`0` 表示页信息不可用。 */
	pages: number,
};

export type PdfUpdatedEvent = PdfUpdated;

/**  打开项目后的项目信息（open_project / get_project 命令输出）。 */
export type ProjectInfo = {
	root: string,
	root_file: string | null,
	/**
	 *  根文件探测得到的候选（升序，项目内绝对路径）。
	 * 
	 *  语义（roadmap P0-②-1）：**仅当未使用手动覆盖时**计算——
	 *  - `Unique(p)` → `[p]`（探测到唯一根文件，`root_file` 即它）；
	 *  - `Multiple(list)` → 全部候选（`root_file` 为 None，**由前端让用户选**）；
	 *  - `None` → 空（`root_file` 为 None，前端退回"列出全部 .tex"）；
	 *  - 手动覆盖生效 → 空（用户已指定，不再探测）。
	 * 
	 *  此前 `Multiple` 的候选列表在命令层被直接丢弃，前端只拿到 `root_file: null`
	 *  且仅有 `console.warn`——表现为「打开项目没反应」。
	 */
	root_candidates: string[],
};

/**  合并后的有效设置（全局 + 项目覆盖）。 */
export type Settings = Settings_Serialize | Settings_Deserialize;

export type SettingsChangedEvent = SettingsChangedEvent_Serialize | SettingsChangedEvent_Deserialize;

export type SettingsChangedEvent_Deserialize = Settings_Deserialize;

export type SettingsChangedEvent_Serialize = Settings_Serialize;

/**
 *  设置局部更新（update_settings 命令载荷，modules.md §6）。
 * 
 *  只改 Some 的键；`root_file` 语义：缺键 = 不动，`null` = 清除覆盖，字符串 = 设置覆盖。
 */
export type SettingsPatch = SettingsPatch_Serialize | SettingsPatch_Deserialize;

/**
 *  设置局部更新（update_settings 命令载荷，modules.md §6）。
 * 
 *  只改 Some 的键；`root_file` 语义：缺键 = 不动，`null` = 清除覆盖，字符串 = 设置覆盖。
 */
export type SettingsPatch_Deserialize = {
	mode?: CompileMode | null,
	debounce_ms?: number | null,
	timeout_secs?: number | null,
	/**
	 *  新建向导开关（roadmap ㊺ §6.13.1-A）：`None` = 不动。**全局**设置，无项目覆盖
	 *  （它是"界面要不要拦一下"，与具体项目无关）。
	 */
	new_file_wizard?: boolean | null,
	/**  关掉一条一次性提示（[`Notice::id`]）：`None` = 不动；空串 / 未知 id 无害。 */
	dismiss_notice?: string | null,
	root_file?: string | null,
	/**
	 *  bundle 来源：`None` = 不动；**空串 = 清除**（回到上游兜底）；其它 = 设置。
	 * 
	 *  用"空串 = 清除"而不是 `Option<Option<..>>`：设置面总是发具体值，用户清空输入框就是清除，
	 *  语义够用且少一层 `null` 歧义（对比 `root_file` 的历史包袱）。
	 */
	bundle?: string | null,
	/**  缓存目录：同上，**空串 = 清除**（回到宿主应用缓存目录）。 */
	cache_dir?: string | null,
	/**  界面主题（roadmap ⑩）：`None` = 不动。 */
	theme?: UiTheme | null,
};

/**
 *  设置局部更新（update_settings 命令载荷，modules.md §6）。
 * 
 *  只改 Some 的键；`root_file` 语义：缺键 = 不动，`null` = 清除覆盖，字符串 = 设置覆盖。
 */
export type SettingsPatch_Serialize = {
	mode?: CompileMode | null,
	debounce_ms?: number | null,
	timeout_secs?: number | null,
	/**
	 *  新建向导开关（roadmap ㊺ §6.13.1-A）：`None` = 不动。**全局**设置，无项目覆盖
	 *  （它是"界面要不要拦一下"，与具体项目无关）。
	 */
	new_file_wizard?: boolean | null,
	/**  关掉一条一次性提示（[`Notice::id`]）：`None` = 不动；空串 / 未知 id 无害。 */
	dismiss_notice?: string | null,
	root_file?: string | null,
	/**
	 *  bundle 来源：`None` = 不动；**空串 = 清除**（回到上游兜底）；其它 = 设置。
	 * 
	 *  用"空串 = 清除"而不是 `Option<Option<..>>`：设置面总是发具体值，用户清空输入框就是清除，
	 *  语义够用且少一层 `null` 歧义（对比 `root_file` 的历史包袱）。
	 */
	bundle?: string | null,
	/**  缓存目录：同上，**空串 = 清除**（回到宿主应用缓存目录）。 */
	cache_dir?: string | null,
	/**  界面主题（roadmap ⑩）：`None` = 不动。 */
	theme?: UiTheme | null,
};

/**  合并后的有效设置（全局 + 项目覆盖）。 */
export type Settings_Deserialize = {
	/**
	 *  schema 版本。
	 * 
	 *  `#[serde(default)]` 是**兜底**：极老的 `settings.json` 可能没有这个键，缺键不该让整份
	 *  配置解析失败（用户设置全丢）。真正的 v1 → v2 迁移在 infra 的存储入口完成（先读 Value 判版本，
	 *  不依赖这个字段）；这里只保证"缺键也能读出一个可用对象"。
	 */
	schema_version?: number,
	compile: CompileSettings,
	/**  Tectonic **资源**（全局：bundle 源 / 缓存目录；形态自 v3 起唯一 = 内嵌，见 [`TectonicSettings`]）。 */
	tectonic?: TectonicSettings,
	/**  界面（全局；`#[serde(default)]` ⇒ 旧 settings.json 没有 `ui` 也能读）。 */
	ui?: UiSettings,
	/**  一次性提示（见 [`Notice`]）；空表不落盘。 */
	notices?: Notice[],
	/**  根文件手动覆盖（探测结果的逃生门，ADR-0009）。 */
	root_file: string | null,
};

/**  合并后的有效设置（全局 + 项目覆盖）。 */
export type Settings_Serialize = {
	/**
	 *  schema 版本。
	 * 
	 *  `#[serde(default)]` 是**兜底**：极老的 `settings.json` 可能没有这个键，缺键不该让整份
	 *  配置解析失败（用户设置全丢）。真正的 v1 → v2 迁移在 infra 的存储入口完成（先读 Value 判版本，
	 *  不依赖这个字段）；这里只保证"缺键也能读出一个可用对象"。
	 */
	schema_version: number,
	compile: CompileSettings,
	/**  Tectonic **资源**（全局：bundle 源 / 缓存目录；形态自 v3 起唯一 = 内嵌，见 [`TectonicSettings`]）。 */
	tectonic: TectonicSettings,
	/**  界面（全局；`#[serde(default)]` ⇒ 旧 settings.json 没有 `ui` 也能读）。 */
	ui: UiSettings,
	/**  一次性提示（见 [`Notice`]）；空表不落盘。 */
	notices?: Notice[],
	/**  根文件手动覆盖（探测结果的逃生门，ADR-0009）。 */
	root_file: string | null,
};

/**  SyncTeX 反向定位结果（PDF → 源码）。 */
export type SourcePositionDto = {
	file: string,
	line: number,
	/**  列号；-1 = 未知（synctex 1.21 输出契约）。 */
	column: number,
};

/**  SyncTeX 正向定位结果（源码 → PDF）。 */
export type SyncTexTarget = {
	page: number,
	x: number | null,
	y: number | null,
};

/**
 *  Tectonic 资源配置（bundle / 缓存目录）；形态位在 v3 随子进程形态一并删除。
 * 
 *  **只在全局设置里**（不进 [`ProjectOverrides`]）：装配点**每趟编译读一次全局设置**（见
 *  `src-tauri` 的 runner 装配）；项目级覆盖要走"资源随 `CompileRequest` 下发"那条路，属后续项
 *  ——现在放一个项目级字段只会是**看着能覆盖、实际不生效**的假开关。
 */
export type TectonicSettings = {
	/**
	 *  bundle 来源：`None`/空 = 上游兜底**网络地址**；否则 `file:///…` 或**相对路径**的目录 bundle。
	 * 
	 *  ⚠ **存储形态**不能是 `E:\…`：上游 `detect_bundle` 会把它当 URL scheme 解析成 `Ok(None)`
	 *  （方案 §5.6 **LB-1**）。入口是宽容的——`E:\…` / `E:/…` / 带引号的「复制为路径」都会被
	 *  [`TectonicSettings::normalize_bundle`] 补成 `file:///…`（`apply_patch` 里归一化在前、
	 *  校验在后），所以 [`super::validate`] 那条只兜底绕过 patch 的写入（手改 `settings.json`）。
	 */
	bundle: string | null,
	/**
	 *  产品缓存目录（`formats/` + `bundles/` 的父目录）：`None`/空 = 宿主的应用缓存目录。
	 * 
	 *  **必须显式给**（或由宿主注入）：上游 format 默认落**项目目录**，不注入就会往用户项目扔
	 *  24 MB 的 `.fmt`（方案 §5.2 硬约束）。
	 */
	cache_dir: string | null,
};

/**  界面设置（全局，与 [`TectonicSettings`] 同层：不进项目覆盖）。 */
export type UiSettings = {
	theme: UiTheme,
};

/**
 *  界面主题（roadmap ⑩）。`System` = 跟随操作系统的深/浅色偏好。
 * 
 *  **默认 `Light`**（不是 `System`）：深色主题是新能力，默认值必须让既有用户升级后**外观不变**
 *  —— 若默认 `System`，系统偏好深色的用户会在升级那一刻被静默换掉整套配色。
 */
export type UiTheme = "light" | "dark" | 
/**  跟随系统（前端读 `prefers-color-scheme`）。 */
"system";

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

